#define MOD 998244353LL

typedef long long ll;

/*
We work on numbers in [0, 2^N - 1].
Operation f:
- if k is odd:  (k - 1) / 2
- if k is even: k / 2 + 2^(N-1)

This is exactly a cyclic right rotation of the N-bit representation by 1 bit.
Therefore, starting from k, repeated application returns to k after
the minimal period of its N-bit string under rotation.

For each k, answer(k) = minimal t >= 1 such that rot^t(k) = k.

We need sum_{k=0}^X answer(k), modulo MOD.

For a fixed d | N, the number of N-bit strings whose minimal period is exactly d
(with respect to rotation) equals:
  primitive[d] = sum_{e | d} mu(d/e) * 2^e
(Mobius inversion on number of strings with period dividing d).

All strings with minimal period d form complete cycles under value order,
but we need only prefix [0..X], not all [0..2^N-1].

Key observation:
The operation is binary rotation, so numbers in [0..X] correspond to N-bit strings
lexicographically <= binary(X). We need, for each d | N, count of strings of minimal
period d not exceeding X.

Any string with period dividing d is determined by its first d bits repeated N/d times.
Let m = N/d and let pattern value be p in [0, 2^d).
The full value is repeat_d_to_N(p). We need count of p such that repeated value <= X.

This count can be found by digit DP / direct comparison:
count_period_dividing(d) = number of d-bit patterns p with repeat(p) <= X.

Then exact minimal-period count in prefix:
exact[d] = count_period_dividing(d) - sum_{e|d, e<d} exact[e]

Answer = sum_{d|N} exact[d] * d mod MOD.

To count patterns p:
Build bits of X. Scan positions 0..N-1.
At position i, repeated bit is p[i % d].
If that bit not assigned yet, decide it.
Standard lexicographic counting:
- if X bit is 1, we may set current pattern bit to 0 and freely choose remaining
  unassigned bits => add 2^(remaining_unassigned_after_assignment)
- then force it to 1 and continue
- if X bit is 0, must force 0
Need consistent assignments when same pattern bit reappears.

Complexities: O(sum_{d|N} N * tau(N))) enough.
*/

static int divisors[200000];
static int dcnt = 0;
static ll pow2mod[200005];

void get_divisors(int n) {
    dcnt = 0;
    for (int i = 1; (ll)i * i <= n; i++) {
        if (n % i == 0) {
            divisors[dcnt++] = i;
            if (i * i != n) divisors[dcnt++] = n / i;
        }
    }
    for (int i = 0; i < dcnt; i++) {
        for (int j = i + 1; j < dcnt; j++) {
            if (divisors[i] > divisors[j]) {
                int t = divisors[i];
                divisors[i] = divisors[j];
                divisors[j] = t;
            }
        }
    }
}

ll count_period_dividing(int N, int d, const char *bits) {
    int *assign = (int*)malloc(sizeof(int) * d);
    for (int i = 0; i < d; i++) assign[i] = -1;

    int assigned = 0;
    ll ans = 0;

    for (int i = 0; i < N; i++) {
        int idx = i % d;
        int xb = bits[i] - '0';

        if (assign[idx] == -1) {
            if (xb == 1) {
                int remaining_unassigned = d - (assigned + 1);
                ans = (ans + pow2mod[remaining_unassigned]) % MOD;
                assign[idx] = 1;
                assigned++;
            } else {
                assign[idx] = 0;
                assigned++;
            }
        } else {
            int b = assign[idx];
            if (b < xb) {
                ans = (ans + pow2mod[d - assigned]) % MOD;
                free(assign);
                return ans;
            } else if (b > xb) {
                free(assign);
                return ans;
            }
        }
    }

    ans = (ans + 1) % MOD; // equal to X
    free(assign);
    return ans;
}

int main(void) {
    int N;
    char X[200005];

    if (scanf("%d %s", &N, X) != 2) return 0;

    int len = 0;
    while (X[len]) len++;

    // Assume X is given as an N-bit binary string.
    // If shorter, left-pad with zeros.
    char *bits = (char*)malloc(N + 1);
    if (len < N) {
        int pad = N - len;
        for (int i = 0; i < pad; i++) bits[i] = '0';
        for (int i = 0; i < len; i++) bits[pad + i] = X[i];
        bits[N] = '\0';
    } else {
        for (int i = 0; i < N; i++) bits[i] = X[i];
        bits[N] = '\0';
    }

    pow2mod[0] = 1;
    for (int i = 1; i <= N; i++) pow2mod[i] = (pow2mod[i - 1] * 2) % MOD;

    get_divisors(N);

    ll *cnt_div = (ll*)calloc(dcnt, sizeof(ll));
    ll *exact = (ll*)calloc(dcnt, sizeof(ll));

    for (int i = 0; i < dcnt; i++) {
        cnt_div[i] = count_period_dividing(N, divisors[i], bits);
    }

    for (int i = 0; i < dcnt; i++) {
        exact[i] = cnt_div[i];
        for (int j = 0; j < i; j++) {
            if (divisors[i] % divisors[j] == 0) {
                exact[i] -= exact[j];
                exact[i] %= MOD;
                if (exact[i] < 0) exact[i] += MOD;
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i < dcnt; i++) {
        ans = (ans + exact[i] * divisors[i]) % MOD;
    }

    printf("%lld\n", ans % MOD);

    free(bits);
    free(cnt_div);
    free(exact);
    return 0;
}

