import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long N = fs.nextLong();
        long X = fs.nextLong();

        // From the operation:
        // odd k  -> (k-1)/2
        // even k -> k/2 + 2^(N-1)
        //
        // This is exactly a cyclic right rotation of an N-bit number.
        // Repeating until returning to the original value gives the orbit size,
        // i.e. the minimal period of the binary string under rotation.
        //
        // We need sum of orbit sizes for all k in [0, X].
        //
        // For a fixed period d, numbers with orbit size dividing d are exactly
        // N-bit strings whose pattern has period d, i.e. determined by first d bits.
        // Let F(d) = count of numbers in [0, X] whose N-bit representation has period d.
        // Then by Möbius inversion over divisors:
        // exact(d) = F(d) - sum exact(e) for e|d, e<d
        // answer = sum exact(d) * d
        //
        // Need F(d): count y in [0, 2^d-1] such that repeating its d-bit block N/d times
        // gives value <= X.

        List<Long> divisors = getDivisors(N);
        Collections.sort(divisors);

        int m = divisors.size();
        long[] F = new long[m];
        long[] exact = new long[m];

        for (int i = 0; i < m; i++) {
            long d = divisors.get(i);
            F[i] = countPeriodicLE(N, d, X);
        }

        long ans = 0;
        for (int i = 0; i < m; i++) {
            long d = divisors.get(i);
            long val = F[i];
            for (int j = 0; j < i; j++) {
                long e = divisors.get(j);
                if (d % e == 0) {
                    val -= exact[j];
                    if (val < 0) val += MOD;
                }
            }
            exact[i] = val % MOD;
            ans += exact[i] * (d % MOD) % MOD;
            ans %= MOD;
        }

        System.out.println(ans % MOD);
    }

    // Count N-bit periodic numbers with period d that are <= X.
    // Such numbers are formed by repeating a d-bit block t = N/d times.
    static long countPeriodicLE(long N, long d, long X) {
        long periodCount = N / d;

        // If d is small enough, compare by constructing repeated value modulo normal long when safe.
        // But N may be huge, so do bitwise lexicographic comparison using X's bits.
        //
        // Let block bits be b[0..d-1] from MSB to LSB in the repeated N-bit string.
        // The repeated number <= X iff the d-bit block interpreted lexicographically
        // against the induced prefix rule is <= maximal allowed block.
        //
        // We compare repeated(block) with X over N bits. Since repeated(block) depends only on d bits,
        // we can determine the number of valid blocks by digit DP on the block bits.
        //
        // At position p in [0, N-1], repeated bit is block[p % d].
        // We process block bits in order 0..d-1. Each chosen bit affects positions
        // p = r, r+d, r+2d, ...
        //
        // For a block prefix, to know if we are already less than X, it is enough to compare
        // at the earliest position among all determined positions where they differ.
        // Since positions are assigned residue by residue, we process residues in increasing order,
        // which is also increasing earliest occurrence positions. Thus simple DP works.

        // DP states:
        // eq = still equal on all processed positions
        // less = already smaller
        long eq = 1, less = 0;

        for (long r = 0; r < d; r++) {
            int xr = getBitFromMSB(X, N, r); // X bit at position r from MSB among N bits

            // Choosing block bit 0 or 1 affects positions r, r+d, ...
            // The first affected position is r itself, which is the earliest not yet processed one.
            // Therefore comparison outcome is determined first by bit at r.
            //
            // If currently equal:
            // choose bit < xr -> becomes less
            // choose bit = xr -> stays equal
            // choose bit > xr -> invalid
            //
            // If currently less:
            // both choices valid.
            long newEq = 0, newLess = 0;

            if (xr == 0) {
                // equal: only choose 0
                newEq = eq;
                // less: choose 0 or 1
                newLess = (less * 2) % MOD;
            } else {
                // xr == 1
                // equal: choose 0 -> less, choose 1 -> equal
                newEq = eq;
                newLess = (less * 2 + eq) % MOD;
            }

            eq = newEq % MOD;
            less = newLess % MOD;
        }

        return (eq + less) % MOD;
    }

    // Get bit at position pos from MSB in an N-bit representation of X.
    // pos = 0 means highest bit among N bits, pos = N-1 means lowest bit.
    // If pos corresponds above actual bits of X, bit is 0.
    static int getBitFromMSB(long X, long N, long pos) {
        long fromLsb = N - 1 - pos;
        if (fromLsb >= 63) return 0; // X fits in signed long input constraints
        return (int)((X >> fromLsb) & 1L);
    }

    static List<Long> getDivisors(long n) {
        List<Long> small = new ArrayList<>();
        List<Long> large = new ArrayList<>();
        for (long i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                small.add(i);
                if (i * i != n) large.add(n / i);
            }
        }
        Collections.reverse(large);
        small.addAll(large);
        return small;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

