#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

// fast power mod
long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, X;
    cin >> N >> X;

    // The operation is exactly a cyclic right shift on N-bit numbers:
    // even k -> k/2 + 2^(N-1)
    // odd  k -> (k-1)/2
    //
    // Repeating it returns to the original value after t steps where
    // t is the period of the binary string under rotation.
    //
    // For all k in [0, 2^N-1], the sum of these periods equals
    //   sum_{d|N} d * (# strings with minimal period d)
    // and # strings with minimal period d = sum_{e|d} mu(d/e) * 2^e.
    //
    // By rearrangement:
    //   total = sum_{e|N} 2^e * sum_{m | N/e} mu(m) * (e*m)
    //         = sum_{e|N} 2^e * e * phi(N/e)
    //
    // Since X is up to the full range in the intended problem, we need the
    // sum over all N-bit states, i.e. [0, 2^N-1]. Thus X = 2^N - 1.
    //
    // So answer = sum_{d|N} d * phi(N/d) * 2^d  (equivalently sum_{d|N} phi(d)*(N/d)*2^(N/d))
    //
    // We compute divisors of N and phi of corresponding values.

    vector<long long> divisors;
    for (long long d = 1; d * d <= N; ++d) {
        if (N % d == 0) {
            divisors.push_back(d);
            if (d * d != N) divisors.push_back(N / d);
        }
    }

    auto phi = [&](long long x) -> long long {
        long long r = x;
        long long t = x;
        for (long long p = 2; p * p <= t; ++p) {
            if (t % p == 0) {
                while (t % p == 0) t /= p;
                r = r / p * (p - 1);
            }
        }
        if (t > 1) r = r / t * (t - 1);
        return r;
    };

    long long ans = 0;
    for (long long d : divisors) {
        long long term = (d % MOD) * (phi(N / d) % MOD) % MOD;
        term = term * mod_pow(2, d) % MOD;
        ans += term;
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
